mapper.select:
SELECT MAX(created_at)
FROM pool_request_samples
WHERE platform_id = #{platformId}

SELECT
    external_account_id,

FROM pool_request_samples
WHERE platform_id = #{platformId}
  AND created_at >= #{from}
  AND created_at < #{to}
GROUP BY external_account_id
ORDER BY external_account_id

SELECT
     AS bucket,

FROM pool_request_samples
WHERE platform_id = #{platformId}
  AND external_account_id = #{externalAccountId}
  AND created_at >= #{from}
  AND created_at < #{to}
GROUP BY bucket
ORDER BY bucket

SELECT external_account_id, AS bucket, COUNT(*) AS requests, COALESCE(SUM(input_tokens), 0)::bigint AS input_tokens, COALESCE(SUM(output_tokens), 0)::bigint AS output_tokens, COALESCE(SUM(cache_read_tokens), 0)::bigint AS cache_read_tokens, COALESCE(SUM(cache_creation_tokens), 0)::bigint AS cache_creation_tokens, COUNT(first_token_ms) AS first_token_samples, AVG(first_token_ms) AS avg_first_token_ms, AVG(duration_ms) AS avg_duration_ms, COALESCE(SUM(actual_cost), 0) AS total_actual_cost FROM pool_request_samples WHERE platform_id = #{platformId} AND created_at >= #{from} AND created_at < #{to}
AND model IN
#{model}
AND external_account_id IN
#{accountId}
GROUP BY external_account_id, bucket ORDER BY external_account_id, bucket

SELECT DISTINCT model
FROM pool_request_samples
WHERE platform_id = #{platformId}
  AND created_at >= #{from}
  AND created_at < #{to}
  AND model IS NOT NULL
ORDER BY model

SELECT
    COALESCE(model, 'unknown') AS model,

FROM pool_request_samples
WHERE platform_id = #{platformId}
  AND external_account_id = #{externalAccountId}
  AND created_at >= #{from}
  AND created_at < #{to}
GROUP BY COALESCE(model, 'unknown')
ORDER BY requests DESC
